from collections import deque

data = sys.stdin.read().split()
s, t = data[0], data[1]
n = len(s)
dist = {s: 0}
q = deque([s])
while q:
    u = q.popleft()
    if u == t:
        break
    for i in range(n):
        for c in 'xyz':
            if c == u[i]:
                continue
            if i > 0 and u[i - 1] == c:
                continue
            if i < n - 1 and u[i + 1] == c:
                continue
            v = u[:i] + c + u[i + 1:]
            if v not in dist:
                dist[v] = dist[u] + 1
                q.append(v)
print(dist[t])

